+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Server Config</title>
+  <style>
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      background: #eef6f1;
+      color: #163322;
+    }
+
+    main {
+      width: min(520px, calc(100% - 32px));
+      padding: 28px;
+      background: white;
+      border: 1px solid #cfe2d5;
+      border-radius: 8px;
+      box-shadow: 0 14px 40px rgba(22, 51, 34, 0.1);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: 30px;
+      line-height: 1.2;
+    }
+
+    p {
+      margin: 0 0 18px;
+      line-height: 1.6;
+    }
+
+    label {
+      display: block;
+      margin: 14px 0 6px;
+      font-size: 14px;
+      font-weight: 600;
+    }
+
+    input,
+    select {
+      width: 100%;
+      height: 42px;
+      padding: 8px 10px;
+      border: 1px solid #abcbb8;
+      border-radius: 6px;
+      color: inherit;
+      font: inherit;
+      background: white;
+    }
+
+    button {
+      width: 100%;
+      height: 42px;
+      margin-top: 20px;
+      border: 0;
+      border-radius: 6px;
+      background: #1d6b3a;
+      color: white;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <h1>Server Config</h1>
+    <p>Review the current defaults and submit changes to the server config endpoint.</p>
+    <form method="post" action="/config">
+      <label for="net-port">Port</label>
+      <input id="net-port" name="net.port" type="number" min="1" max="65535" value="8080" required>
+
+      <label for="net-backlog">Backlog</label>
+      <input id="net-backlog" name="net.backlog" type="number" min="1" value="10" required>
+
+      <label for="net-worker-count">Worker Count</label>
+      <input id="net-worker-count" name="net.worker_count" type="number" min="1" value="10" required>
+
+      <label for="net-reuse-address">Reuse Address</label>
+      <select id="net-reuse-address" name="net.reuseAddress">
+        <option value="true" selected>true</option>
+        <option value="false">false</option>
+      </select>
+
+      <label for="http-max-body-size">Max Body Size</label>
+      <input id="http-max-body-size" name="http.max_body_size" type="number" min="0" value="1048576" required>
+
+      <label for="http-max-header-size">Max Header Size</label>
+      <input id="http-max-header-size" name="http.max_header_size" type="number" min="1" value="8192" required>
+
+      <button type="submit">Save config</button>
+    </form>
+  </main>
+</body>
+</html>
*** End Patch

